import json,copy
from pathlib import Path
base=Path('content/isc2-cc-2026/learning/published');l=copy.deepcopy(json.loads((base/'lessons/lesson-d1-10-control-categories.json').read_text(encoding='utf-8')))
def pair(en,th):return {'en':en,'th':th}
def row(*v):return [pair(*x) for x in v]
slides=[]
def add(suffix,kind,title,lead,rows,detail,foot,refs=[]):
 s=copy.deepcopy(l['slides'][0]);s.update(id='slide-'+suffix,title=pair(*title),layoutId='control-functions-'+kind,rendererId='interactive' if kind=='context' else 'comparison');s['blocks']=[{'kind':'text','text':pair(*lead)},{'kind':'table','caption':pair('Course concepts and original teaching examples','แนวคิดจากโน้ตและตัวอย่างแต่งขึ้นเพื่อเรียน'),'columns':[pair('Concept','แนวคิด'),pair('Action or effect','การกระทำหรือผล'),pair('Limit or context','ข้อจำกัดหรือบริบท')],'rows':rows},{'kind':'text','text':pair(*detail)},{'kind':'text','text':pair(*foot)}];s['referenceIds']=['ref-outline','ref-a','ref-b']+refs;slides.append(s)
add('01-category-and-function','lenses',('One control can have a category and several functions.','Control เดียวมีทั้ง Category และหลาย Function ได้'),('Ask how it works—and what it accomplishes in this context.','ถามทั้งกลไกที่ใช้ และผลที่ทำได้ในบริบทนี้'),[
row(('Category','Category'),('A firewall applies software rules: Technical.','Firewall ใช้กฎซอฟต์แวร์: Technical'),('How the mechanism is implemented.','อธิบายกลไกที่ใช้')),
row(('Function','Function'),('Blocking: Preventive. Alerting: Detective.','บล็อก: Preventive แจ้งเตือน: Detective'),('What the configured action achieves.','อธิบายผลของงานที่ตั้งค่าไว้'))],
('L10 taught technical, administrative and physical categories. A §§35,37,44 and B §6 distinguish these from functions: the outcome a safeguard is designed or used to achieve. A firewall can enforce a blocking rule and generate evidence/alerts; its technical category does not exclude preventive and detective functions. The functions are not mutually exclusive labels. Classify the stated action rather than assuming every installation enables every capability. The official 2026 Objective 1.4 lists three categories; this function taxonomy is source-based supporting course depth, not a new set of official numbered requirements. The lesson covers A’s directive function and B’s recovery function as complementary teaching terms, with overlap explained. A product name or a single keyword is insufficient evidence of its actual effect.',
'L10 สอน Technical, Administrative และ Physical แล้ว A §§35,37,44 กับ B §6 แยกสิ่งเหล่านี้ออกจาก Function ซึ่งคือผลที่มาตรการถูกออกแบบหรือใช้ให้เกิด Firewall อาจบังคับกฎบล็อกและสร้างหลักฐานหรือ Alert ได้ Category แบบ Technical ไม่ตัดหน้าที่ Preventive และ Detective ออก หน้าที่เหล่านี้ไม่ได้จำเป็นต้องเลือกได้เพียงอย่างเดียว ต้องดูการกระทำที่ระบุ ไม่สมมติว่าทุกระบบเปิดใช้ทุกความสามารถ Objective 1.4 ปี2026 ทางการระบุสาม Category ส่วนชุด Function นี้เป็นความลึกเสริมจากโน้ต ไม่ใช่ข้อกำหนดทางการที่เพิ่มเลขใหม่ บทนี้สอน Directive จาก A และ Recovery จาก B เป็นคำที่ช่วยกัน พร้อมอธิบายส่วนทับซ้อน ชื่อผลิตภัณฑ์หรือ Keyword เดียวไม่ใช่หลักฐานว่าทำงานได้จริง'),('Category and function describe different aspects of the same control.','Category และ Function บอกคนละมุมของ Control เดียวกัน'))
add('02-preventive','prevent',('Preventive controls act before an unwanted action succeeds.','Preventive Controls ทำงานก่อนการกระทำที่ไม่ต้องการสำเร็จ'),('Enforce a condition that blocks or reduces an unwanted outcome.','บังคับเงื่อนไขเพื่อหยุดหรือลดโอกาสผลที่ไม่ต้องการ'),[
row(('Attempt','ความพยายาม'),('An unauthorised account requests a sensitive file.','บัญชีไม่มีสิทธิ์ขออ่านไฟล์สำคัญ'),('A request is not permission.','การขอไม่ได้แปลว่าได้รับอนุญาต')),
row(('Enforcement gate','จุดบังคับใช้'),('An access rule denies the request.','กฎสิทธิ์ปฏิเสธคำขอ'),('The unwanted read is blocked.','หยุดการอ่านที่ไม่ได้รับอนุญาต')),
row(('Limit','ข้อจำกัด'),('Wrong rules or bypass paths can leave gaps.','กฎผิดหรือทางข้ามยังสร้างช่องว่าง'),('Verify the intended protection.','ตรวจว่าปกป้องได้ตามต้องการ'))],
('A §39 and B §6.2 describe preventive controls as acting to stop an unwanted activity before it succeeds. Authentication, access rules, locks and appropriately applied encryption can support preventive outcomes, but the precise claim depends on what is being prevented. This original example uses an ACL to deny an unauthorised read. A locked room restricts physical entry through a different category; an approved process can also reduce the likelihood of a bad decision. Preventive does not mean every attack is impossible or that the control acts only before any incident has begun: a rule can prevent the next harmful action during an ongoing event. Misconfiguration, stolen authorised credentials or a bypass may remain. A warning alone does not enforce the condition. Explain the stopped action and test the mechanism rather than labelling a tool preventive forever.',
'A §39 และ B §6.2 อธิบาย Preventive ว่าหยุดกิจกรรมที่ไม่ต้องการก่อนสำเร็จ Authentication กฎสิทธิ์ ล็อก และ Encryption ที่ใช้เหมาะสมช่วยป้องกันได้ แต่ต้องระบุว่าป้องกันอะไร ตัวอย่างแต่งขึ้นนี้ใช้ ACL ปฏิเสธการอ่านโดยไม่มีสิทธิ์ ส่วนห้องล็อกจำกัดการเข้าโดยใช้ Category อื่น และกระบวนการที่อนุมัติก็ลดโอกาสตัดสินใจผิดได้ Preventive ไม่ได้แปลว่าโจมตีไม่ได้ทุกแบบ หรือทำงานได้เฉพาะก่อนเหตุทั้งหมดเริ่ม กฎอาจหยุดการกระทำอันตรายถัดไประหว่างเหตุที่ดำเนินอยู่ได้ การตั้งค่าผิด Credential ที่มีสิทธิ์ถูกขโมย หรือทางข้ามอาจยังเหลือ คำเตือนอย่างเดียวไม่ได้บังคับเงื่อนไข ต้องอธิบายว่างานใดถูกหยุดและทดสอบกลไก ไม่ติดป้ายผลิตภัณฑ์ว่า Preventive ตลอดทุกบริบท'),('Identify the action being prevented—not a promise of zero risk.','ระบุงานที่ถูกป้องกัน ไม่ใช่อ้างว่า Risk เป็นศูนย์'))
add('03-detective','detect',('Detective controls make relevant activity discoverable.','Detective Controls ช่วยให้ค้นพบกิจกรรมที่เกี่ยวข้อง'),('Observation and evidence need a working path to review or response.','การสังเกตและหลักฐานต้องมีทางไปสู่การตรวจหรือรับมือ'),[
row(('Activity','กิจกรรม'),('An unusual access attempt occurs.','เกิดความพยายามเข้าถึงผิดปกติ'),('It may be suspicious—not yet confirmed malicious.','อาจน่าสงสัย แต่ยังไม่ยืนยันว่าโจมตี')),
row(('Detection','การตรวจพบ'),('Monitoring generates an alert or useful record.','Monitoring สร้าง Alert หรือบันทึกที่ใช้ได้'),('Collection and configuration matter.','การเก็บข้อมูลและการตั้งค่ามีผล')),
row(('Follow-through','การทำต่อ'),('An assigned team reviews and escalates.','ทีมที่รับผิดชอบตรวจและยกระดับ'),('An alert alone does not block the attempt.','Alert อย่างเดียวไม่ได้บล็อกความพยายาม'))],
('A §40 and B §6.2 give IDS, audit trails, monitoring and motion detection as detective examples. The function is to discover relevant activity or conditions through observation and evidence. In this authored scenario, monitoring flags unusual access and a responsible team checks the context; not every alert is a proven attack. Useful detection requires appropriate collection, visibility, rules and follow-up. A log that is never collected or examined may fail to reveal a problem in practice. Detection may happen during activity or later when recordings are reviewed; it is not restricted to a universal point in time. A detection alert is not automatically a preventive block. If the system also blocks the connection, those are separate configured actions that can support multiple functions. Detailed log operations and incident-response procedures remain outside this control-function unit.',
'A §40 และ B §6.2 ยก IDS, Audit Trail, Monitoring และการตรวจจับการเคลื่อนไหวเป็นตัวอย่าง Detective หน้าที่คือค้นพบกิจกรรมหรือสภาพที่เกี่ยวข้องผ่านการสังเกตและหลักฐาน ตัวอย่างแต่งขึ้นนี้ Monitoring แจ้งการเข้าถึงผิดปกติ แล้วทีมที่รับผิดชอบตรวจบริบท ไม่ใช่ทุก Alert ยืนยันว่าโจมตี การตรวจที่ใช้ได้ต้องมีข้อมูลที่เหมาะ มองเห็นกิจกรรม ตั้งกฎ และมีคนทำต่อ Log ที่ไม่เก็บหรือไม่ตรวจอาจไม่ช่วยให้พบปัญหาจริง การตรวจอาจเกิดระหว่างกิจกรรมหรือภายหลังเมื่อดูบันทึก จึงไม่จำกัดเวลาแบบเดียว Alert ไม่ได้เป็นการบล็อกอัตโนมัติ ถ้าระบบบล็อกด้วย นั่นคืออีกการกระทำที่ตั้งค่าและทำได้หลายหน้าที่ รายละเอียดการทำ Log และขั้นตอน Incident Response อยู่นอกบทหน้าที่ Control นี้'),('Finding a problem and stopping it are different effects.','การพบปัญหากับการหยุดปัญหาเป็นคนละผล'))
add('04-corrective-and-recovery','restore',('Fix the problem—and restore trusted operation.','แก้ปัญหา และฟื้นการทำงานที่เชื่อถือได้'),('Corrective and recovery are useful distinctions with possible overlap.','Corrective กับ Recovery แยกจุดเน้นได้ แต่ทับซ้อนกันได้'),[
row(('Corrective','Corrective'),('Repair the identified weakness or harmful condition.','แก้จุดอ่อนหรือสภาพที่เป็นปัญหา'),('Example: correct the configuration after investigation.','ตัวอย่าง: แก้ค่าที่ผิดหลังตรวจสอบ')),
row(('Recovery','Recovery'),('Restore the required data or service.','ฟื้นข้อมูลหรือบริการที่ต้องใช้'),('Example: restore a verified clean backup.','ตัวอย่าง: กู้จาก Backup สะอาดที่ตรวจแล้ว'))],
('A §41 uses corrective broadly for fixing damage, restoring or reducing harm, including backup restoration; B §6.2 separately names recovery for restoring operation. This lesson reconciles the notes: corrective focuses on fixing an identified problem, while recovery highlights restoring needed capabilities, but overlap is valid and not a rigid universal boundary. In this original example, the team investigates a bad configuration, corrects it and restores validated clean data. Restoring data without addressing the cause can recreate the incident; fixing a setting alone may not recover lost data. A patch installed before exploitation may be preventive, while repairing an identified problem may be corrective—read the action and context. Validate integrity and safe operation before return to service. Neither an available backup nor a recovery label guarantees a successful restore. NIST recovery terminology supports restoration of missions/functions; full BC/DR planning is outside this lesson.',
'A §41 ใช้ Corrective กว้างถึงแก้ความเสียหาย ฟื้นฟู หรือลดผลเสีย รวมการกู้ Backup ส่วน B §6.2 แยก Recovery สำหรับฟื้นการทำงาน บทนี้เทียบว่า Corrective เน้นแก้ปัญหาที่พบ ส่วน Recovery เน้นคืนความสามารถที่ต้องใช้ แต่ทับซ้อนกันได้ ไม่ใช่ขอบเขตสากลตายตัว ตัวอย่างแต่งขึ้นคือทีมตรวจค่าที่ผิด แก้ไข แล้วกู้ข้อมูลสะอาดที่ตรวจยืนยัน การกู้ข้อมูลโดยไม่จัดการสาเหตุอาจเกิดเหตุซ้ำ การแก้ค่าอย่างเดียวอาจไม่คืนข้อมูลที่หาย Patch ก่อนถูกใช้โจมตีอาจเชิง Preventive ส่วนแก้ปัญหาที่พบอาจเป็น Corrective ต้องอ่านงานและบริบท ตรวจ Integrity และการทำงานปลอดภัยก่อนกลับบริการ มี Backup หรือชื่อ Recovery ก็ไม่ได้รับประกันว่าจะกู้สำเร็จ NIST อธิบาย Recovery เชื่อมการฟื้นภารกิจและงาน รายละเอียด BC/DR อยู่นอกบทนี้'),('Repairing the cause and restoring service can both be necessary.','อาจต้องทั้งแก้สาเหตุและฟื้นบริการ'),['ref-recovery'])
add('05-deterrent','deter',('Deterrent controls aim to discourage the attempt.','Deterrent Controls มุ่งยับยั้งไม่ให้เริ่มพยายาม'),('Visibility and perceived consequences influence behaviour.','การมองเห็นมาตรการและผลที่คาดว่าจะตามมามีผลต่อพฤติกรรม'),[
row(('Visible signal','สัญญาณที่เห็นได้'),('A visible camera or warning communicates scrutiny.','กล้องที่เห็นชัดหรือป้ายเตือนสื่อว่ามีการเฝ้าดู'),('The intended effect is discouragement.','มุ่งให้ผู้กระทำลังเลหรือไม่ทำ')),
row(('Limit','ข้อจำกัด'),('A determined person may still proceed.','คนที่ตั้งใจอาจยังลงมือ'),('The sign does not physically stop entry.','ป้ายไม่ได้หยุดการผ่านเข้าจริง'))],
('A §38 and B §6.2 describe deterrence as discouraging unwanted behaviour. A visible guard, camera or warning can signal scrutiny and consequences. In this authored facility example, the intended outcome of a visible camera is that a person decides not to attempt an unauthorised entry. That is not the same as a locked barrier physically preventing passage, and it does not prove that the camera is monitored or recording. If recordings are reviewed, detective work is also present; if a guard stops an entry, a preventive action is present. Visibility alone provides no guarantee that every person is deterred. A sign can also communicate instructions, so its directive role may coexist with deterrence. Explain the intended behavioural effect and the operational limits rather than relying on the object name. Different functions can exist within the same installation.',
'A §38 และ B §6.2 อธิบาย Deterrent ว่ายับยั้งพฤติกรรมที่ไม่ต้องการ เจ้าหน้าที่ กล้อง หรือป้ายที่เห็นชัดสื่อว่ามีการเฝ้าดูและผลตามมา ตัวอย่างสถานที่แต่งขึ้นนี้มุ่งให้คนเห็นกล้องแล้วตัดสินใจไม่ลองเข้าพื้นที่โดยไม่มีสิทธิ์ ไม่เหมือนประตูล็อกที่ป้องกันการผ่านจริง และไม่ได้พิสูจน์ว่ากล้องบันทึกหรือมีคนดู ถ้าตรวจภาพจะมี Detective ด้วย ถ้าเจ้าหน้าที่หยุดคนเข้าก็มีงาน Preventive การมองเห็นอย่างเดียวไม่รับประกันว่าทุกคนจะยับยั้งตนเอง ป้ายยังอาจบอกคำสั่ง จึงมี Directive ควบคู่ได้ ต้องอธิบายผลต่อพฤติกรรมและข้อจำกัดการทำงาน ไม่อาศัยชื่อสิ่งของ ระบบเดียวมีหลายหน้าที่ได้'),('Discouragement is useful; it is not guaranteed enforcement.','การยับยั้งมีประโยชน์ แต่ไม่ใช่บังคับใช้ได้แน่นอน'))
add('06-directive','direct',('Directive controls communicate the expected action.','Directive Controls สื่อสิ่งที่คาดหวังให้ปฏิบัติ'),('Rules and instructions guide behaviour; enforcement is another mechanism.','กฎและคำสั่งชี้พฤติกรรม ส่วนการบังคับใช้เป็นอีกกลไก'),[
row(('Instruction','คำชี้แนวทาง'),('Verify visitor authorisation before admitting entry.','ตรวจการอนุญาตผู้มาติดต่อก่อนให้เข้า'),('An approved procedure states the expected action.','Procedure ที่อนุมัติบอกสิ่งที่ต้องทำ')),
row(('Application','การนำไปใช้'),('Staff understand and follow the instruction.','เจ้าหน้าที่เข้าใจและทำตาม'),('A rule on paper does not operate the door.','ข้อความในเอกสารไม่ได้ควบคุมประตูเอง'))],
('A §43 names directive controls as guiding or directing behaviour through policy, procedures, standards, guidance or signs. B §7.1 and L09 already distinguish those document functions. Directive is useful course terminology, not an additional official 1.4 heading. In this authored visitor example, an approved instruction tells staff to verify authorisation before entry. The instruction can reduce mistakes when understood and followed, while a lock and access checks provide separate enforcement. A document alone cannot ensure compliance. A guideline can guide behaviour without becoming a mandatory requirement merely because it is directive; actual authority and adoption still matter. A sign that both states a rule and warns of consequences can serve directive and deterrent purposes. This function does not require repeating the full policy hierarchy or introducing ethics content reserved for L12.',
'A §43 เรียก Directive ว่าชี้หรือกำกับพฤติกรรมผ่าน Policy, Procedure, Standard, Guideline หรือป้าย B §7.1 และ L09 แยกหน้าที่เอกสารแล้ว Directive เป็นคำเสริมในคอร์ส ไม่ใช่หัวข้อทางการ1.4ที่เพิ่มขึ้น ตัวอย่างผู้มาติดต่อแต่งขึ้นนี้คำสั่งที่อนุมัติบอกให้เจ้าหน้าที่ตรวจการอนุญาตก่อนให้เข้า คำสั่งช่วยลดความผิดพลาดเมื่อเข้าใจและทำตาม ส่วนล็อกและการตรวจสิทธิ์เป็นกลไกบังคับใช้อีกส่วน เอกสารอย่างเดียวรับประกัน Compliance ไม่ได้ Guideline ชี้พฤติกรรมได้โดยไม่ได้กลายเป็นข้อบังคับเพราะชื่อ Directive ยังต้องดูอำนาจและการรับใช้จริง ป้ายที่บอกกฎพร้อมผลตามมาอาจมีทั้ง Directive และ Deterrent บทนี้ไม่ต้องสอนลำดับเอกสารซ้ำเต็มหรือเริ่ม Ethics ที่เป็น L12'),('Guiding behaviour does not make every instruction self-enforcing.','ชี้แนวทางแล้วไม่ได้แปลว่าคำสั่งบังคับตัวเองได้'))
add('07-compensating','compensate',('A compensating control must address the original protection need.','Compensating Control ต้องตอบความต้องการปกป้องเดิม'),('An alternative needs justified comparable protection—not just a different tool.','ทางเลือกต้องมีเหตุผลว่าปกป้องได้เทียบเคียง ไม่ใช่แค่เปลี่ยนเครื่องมือ'),[
row(('Constraint','ข้อจำกัด'),('The required primary mechanism cannot be used.','กลไกหลักที่กำหนดไม่สามารถใช้ได้'),('Document the requirement and the real limitation.','บันทึกข้อกำหนดและข้อจำกัดจริง')),
row(('Assessed alternative','ทางเลือกที่ประเมิน'),('Assess combined safeguards against the same risk.','ประเมินมาตรการร่วมต่อ Risk เดิม'),('Demonstrate equivalent or comparable protection.','แสดงการปกป้องที่เทียบเท่าหรือเทียบเคียง')),
row(('Authorised decision','การตัดสินใจตามอำนาจ'),('Record rationale, approval, residual risk and review.','บันทึกเหตุผล การอนุมัติ Risk ที่เหลือ และการทบทวน'),('An internal decision cannot waive external duties.','การตัดสินใจภายในไม่ลบหน้าที่ภายนอก'))],
('A §42 and B §6.2 describe a compensating control as an alternative when the primary control cannot be implemented. NIST defines compensation in terms of equivalent or comparable protection; its baseline-tailoring guidance requires a rationale addressing the same requirement. This original conceptual example starts with an unmet protection requirement, documents the constraint, evaluates a combination of restrictions and monitoring, then seeks the authorised decision and ongoing review. It does not certify any particular workaround as equivalent. Extra monitoring alone may only reveal harm after it occurs and may not replace the required preventive protection. Cheaper, easier or merely additional is not automatically compensating. Whether an exception is permitted depends on the applicable requirement and authority; internal acceptance cannot waive a law or contractual obligation. Compensating describes the alternative role relative to another control, so it can also have preventive, detective or other functions. It is not the same as recovery after an incident.',
'A §42 และ B §6.2 อธิบาย Compensating ว่าใช้ทางเลือกเมื่อทำ Control หลักไม่ได้ NIST เน้นการปกป้องที่เทียบเท่าหรือเทียบเคียง และแนวทางปรับ Baseline ต้องมีเหตุผลตอบข้อกำหนดเดิม ตัวอย่างเชิงแนวคิดแต่งขึ้นนี้เริ่มจากสิ่งที่ยังปกป้องไม่ได้ บันทึกข้อจำกัด ประเมินข้อจำกัดการเข้าถึงร่วมกับ Monitoring แล้วขอการตัดสินใจตามอำนาจและทบทวนต่อ ไม่ได้ยืนยันว่าทางแก้แบบใดเทียบเท่าแน่นอน เพิ่ม Monitoring อย่างเดียวอาจเพียงพบความเสียหายภายหลัง ไม่แทนการป้องกันที่ต้องมี ถูกกว่า ง่ายกว่า หรือเป็นมาตรการเสริมไม่ได้แปลว่า Compensating อัตโนมัติ อนุญาตข้อยกเว้นหรือไม่ขึ้นกับข้อกำหนดและอำนาจ การยอมรับภายในไม่ลบกฎหมายหรือสัญญา คำนี้บอกบทบาททดแทนเมื่อเทียบกับอีก Control จึงอาจมีหน้าที่ Preventive/Detective หรือแบบอื่นร่วมด้วย ไม่ใช่สิ่งเดียวกับ Recovery หลังเหตุ'),('Alternative + comparable protection + authorised review.','ทางเลือก + ปกป้องเทียบเคียง + ทบทวนตามอำนาจ'),['ref-compensation','ref-baselines'])
add('08-context-changes-function','context',('The same camera can support different functions.','กล้องเดียวสนับสนุนหน้าที่ต่างกันได้'),('Choose a stated use and inspect the effect—not a permanent product label.','เลือกวิธีใช้ที่ระบุ แล้วดูผล ไม่ติดป้ายตายตัวกับผลิตภัณฑ์'),[
row(('Visible presence','เห็นกล้องชัด'),('Deterrent: intended to discourage an entry attempt.','Deterrent: มุ่งยับยั้งไม่ให้ลองเข้าพื้นที่'),('Visibility alone does not prove recording or blocking.','เห็นกล้องไม่ได้พิสูจน์ว่าบันทึกหรือบล็อก')),
row(('Reviewed recording','ตรวจภาพที่บันทึก'),('Detective: review reveals an unauthorised entry.','Detective: ตรวจภาพแล้วพบการเข้าโดยไม่มีสิทธิ์'),('Finding evidence later does not undo the entry.','พบหลักฐานภายหลังไม่ได้ย้อนหยุดการเข้า')),
row(('Alert and intervention','แจ้งและเข้าหยุด'),('Detection alerts a guard; the guard stops the attempted entry.','ตรวจพบแล้วแจ้งเจ้าหน้าที่ ซึ่งหยุดความพยายามเข้า'),('Detective + Preventive across the combined actions.','Detective + Preventive จากการกระทำที่ทำร่วมกัน'))],
('This original context exercise applies A §44 and B §§6.2–6.3. All three uses can occur in one installation; selecting a context does not claim other functions are impossible. Visible presence is deterrent when intended to discourage. Reviewing recordings can detect an entry after the event. In the explicitly combined third scenario, detection alerts a guard and the guard actually stops an attempted entry, so detective and preventive effects are both supported by stated facts. The camera does not physically block by itself, and a recording without review is not proof of timely detection. The system still includes physical protection and technical components from the category perspective taught in L10. Context buttons inspect use cases, not scored single-answer questions; feedback supports multiple valid functions where facts justify them. Both languages and keyboard activation retain Viewer navigation and independent progress without new storage fields.',
'แบบฝึกบริบทแต่งขึ้นนี้ใช้ A §44 และ B §§6.2–6.3 ระบบเดียวทำได้ทั้งสามวิธี เลือกบริบทหนึ่งไม่ได้อ้างว่าหน้าที่อื่นเป็นไปไม่ได้ การเห็นกล้องชัดเป็น Deterrent เมื่อมุ่งยับยั้ง ตรวจภาพบันทึกช่วยพบการเข้าภายหลัง ส่วนกรณีที่สามระบุชัดว่าตรวจพบแล้วแจ้งเจ้าหน้าที่ และเจ้าหน้าที่หยุดความพยายามเข้าจริง จึงมีผลทั้ง Detective และ Preventive ตามข้อเท็จจริงที่ให้ กล้องไม่ได้กั้นทางเอง และมีภาพแต่ไม่ตรวจไม่ได้พิสูจน์ว่าพบทันเวลา ในมุม Category ยังมี Physical และองค์ประกอบ Technical ตาม L10 ปุ่มบริบทใช้ดูตัวอย่าง ไม่ใช่คำถามคะแนนที่บังคับคำตอบเดียว Feedback ยอมรับหลายหน้าที่เมื่อมีเหตุผลรองรับ ทั้งสองภาษาและคีย์บอร์ดไม่รบกวนการนำทางหรือ Progress และไม่เพิ่มช่องข้อมูลเก็บถาวร'),('State the use, then justify every claimed function.','ระบุวิธีใช้ แล้วให้เหตุผลทุกหน้าที่ที่อ้าง'))
add('09-reason-from-effects','reason',('Explain the effect and the evidence behind the label.','อธิบายผลและหลักฐานที่รองรับชื่อหน้าที่'),('Timing is a clue; actual operation determines the claim.','เวลาเป็นเบาะแส แต่ต้องดูการทำงานจริง'),[
row(('Intent and action','เจตนาและการกระทำ'),('What unwanted outcome is addressed—and how?','จัดการผลที่ไม่ต้องการอะไร และอย่างไร?'),('Name the described mechanism and function.','ระบุกลไกและหน้าที่ตามที่อธิบาย')),
row(('Evidence and limits','หลักฐานและข้อจำกัด'),('What shows it works, and what can still fail?','อะไรยืนยันว่าได้ผล และยังผิดพลาดตรงไหน?'),('Do not assume an alert also blocks.','อย่าสมมติว่า Alert บล็อกด้วย')),
row(('Combined protection','การปกป้องร่วม'),('Use complementary controls and reassess changes.','ใช้ Controls เสริมกันและทบทวนเมื่อเปลี่ยน'),('One action can support more than one function.','การกระทำเดียวอาจสนับสนุนหลายหน้าที่'))],
('A §45 offers memory cues, while A §44 and B §6.3 require context. Use the cues to start reasoning, not as guaranteed exam shortcuts. A timeline of discourage, prevent, detect and correct can illustrate effects, but real controls overlap and operate continuously rather than in a universal one-way sequence. A patch may prevent exploitation or correct an identified weakness; restoring service can be recovery and broadly corrective; an alternative safeguard may compensate and detect at the same time. Explain the actual purpose, mechanism, operating evidence and limitations. This lesson completes the planned function depth alongside L10 categories without inventing official sub-objective headings. The coverage audit compares the official outline and both notes, not just the existence of slides. Human academic/bilingual acceptance remains pending. Professional conduct, due care/diligence and ethics remain L12 and are not implemented here.',
'A §45 ให้คำช่วยจำ แต่ A §44 และ B §6.3 ให้ดูบริบท ใช้คำเหล่านี้เริ่มวิเคราะห์ ไม่ใช่สูตรรับประกันข้อสอบ เส้นเวลา ยับยั้ง ป้องกัน ตรวจพบ และแก้ไขช่วยอธิบายผล แต่ระบบจริงทับซ้อนและทำต่อเนื่อง ไม่ใช่ลำดับทางเดียวสากล Patch อาจป้องกันการใช้ช่องโหว่หรือแก้จุดอ่อนที่พบ การฟื้นบริการเป็น Recovery และ Corrective ในความหมายกว้างได้ ทางเลือกอาจทั้ง Compensating และ Detective ต้องอธิบายจุดประสงค์ กลไก หลักฐานการทำงาน และข้อจำกัด บทนี้เติมความลึกหน้าที่ตามแผนควบคู่ Category ใน L10 โดยไม่เพิ่มหัวข้อทางการใหม่ Audit จะเทียบ Outline กับโน้ตทั้งสอง ไม่ดูแค่มีสไลด์ ยังต้องให้มนุษย์ยอมรับวิชาการและภาษา Professional Conduct, Due Care/Diligence และ Ethics ยังเป็น L12 ซึ่งไม่ได้เริ่มในงานนี้'),('Describe → explain → verify → revisit.','อธิบายสิ่งที่ทำ → ให้เหตุผล → ตรวจผล → ทบทวน'))
l.update(id='lesson-d1-11-control-functions',title=pair('What Is the Control Doing?','Control นี้ทำหน้าที่อะไร?'),synopsis=pair('Explain security-control functions, their limits and overlap through contextual examples.','อธิบายหน้าที่ ข้อจำกัด และส่วนทับซ้อนของ Controls จากบริบท'),outcomes=[pair('Distinguish implementation categories from functions without treating them as exclusive.','แยก Category ตามกลไกกับ Function โดยไม่มองว่าเลือกได้เพียงชุดเดียว'),pair('Explain preventive, detective, corrective, recovery, deterrent, directive and compensating effects.','อธิบายผลแบบ Preventive, Detective, Corrective, Recovery, Deterrent, Directive และ Compensating'),pair('Justify multiple functions using the stated design and use of a control.','ให้เหตุผลหลายหน้าที่จากการออกแบบและวิธีใช้ที่ระบุ'),pair('Evaluate the protection, evidence and limitations behind a function label.','ประเมินการปกป้อง หลักฐาน และข้อจำกัดที่รองรับชื่อหน้าที่')],prerequisites=[pair('Recommended: Control Categories (Lesson 10), risk and governance foundations.','แนะนำ Control Categories (Lesson 10) พร้อมพื้นฐาน Risk และ Governance')],slides=slides,slideOrder=[s['id'] for s in slides])
